export function lightningPoints(data,now=Date.now()){
 if(!Array.isArray(data?.features))throw Error("Invalid lightning feed");
 const seen=new Set();
 return data.features.flatMap(f=>{
 const c=f?.geometry?.coordinates,t=Date.parse(f?.properties?.observed);
 if(f?.geometry?.type!=="Point"||!Array.isArray(c)||!Number.isFinite(c[0])||!Number.isFinite(c[1])||Math.abs(c[0])>180||Math.abs(c[1])>90||!Number.isFinite(t)||t>now||t<now-3600000)return [];
 const key=f.id||c.join(",")+t;if(seen.has(key))return [];seen.add(key);
 return [{lon:c[0],lat:c[1],time:t}];
 }).slice(0,1000);
}
export function observedWind(speed,direction,gust){
 if(!speed||!direction||!speed.station||speed.station!==direction.station||![speed,direction].every(v=>Number.isFinite(Date.parse(v.observed)))||Math.abs(Date.parse(speed.observed)-Date.parse(direction.observed))>600000)return null;
 if(!Number.isFinite(speed.value)||speed.value<0||!Number.isFinite(direction.value)||direction.value<0||direction.value>360)return null;
 return {current:{wind_speed_10m:speed.value*3.6,wind_direction_10m:direction.value,wind_gusts_10m:gust?.station===speed.station&&Math.abs(Date.parse(gust.observed)-Date.parse(speed.observed))<=600000&&Number.isFinite(gust.value)&&gust.value>=0?gust.value*3.6:null},source:"DMI"};
}
